// BENCHMARK MANUEL UNIQUEMENT : modifier ces deux paramètres pour un essai.
// Ne jamais y coller de clés, brouillons privés, identifiants, ni recettes non publiques.
const model='llama3.2:latest'; // puis qwen3:8b / gemma3:12b si installés
const kind='culture'; // recette | atelier | culture | ingredient | technique
if(!['llama3.2:latest','qwen3:8b','gemma3:12b'].includes(model))throw Error('BENCH_MODEL');
if(!['recette','atelier','culture','ingredient','technique'].includes(kind))throw Error('BENCH_KIND');
const cases={
 recette:['Recette cambodgienne : brief sans mesures fournies','Ne pas inventer ingrédients, cuisson ni quantités.'],
 atelier:['Atelier théorique autour d’une recette canonique','Aucun ID de recette validée fourni : ne pas prétendre atelier publiable ni audio validé.'],
 culture:['Les marchés comme lieux de vie au Cambodge','Aucune source historique ni témoignage fournis : rester documentaire et prudent.'],
 ingredient:['Le galanga et ses usages culinaires','Pas de preuve de bénéfice médical ni de durée de conservation fournie.'],
 technique:['Les gestes du mortier','Aucun test pratique documenté : noter les précautions à vérifier.']
};
const [title,fact]=cases[kind];
const limits={title:180,angle:700,summary:2000,research_note:3000};
const properties=Object.fromEntries(Object.entries(limits).map(([name,maxLength])=>[name,{type:'string',minLength:1,maxLength}]));
const request={
 model,stream:false,think:false,keep_alive:'1m',
 options:{temperature:0,num_predict:1200,num_ctx:4096},
 format:{type:'object',properties,required:Object.keys(properties),additionalProperties:false},
 messages:[
 {role:'system',content:'Rédige en français un BRIEF non approuvé. JSON uniquement : title, angle, summary, research_note. Ne pas inventer faits, recettes, témoignages, droits, sources ou MP3. Un Carnet culturel n’est pas une recette. Les notes sont privées, la publication est interdite.'},
 {role:'user',content:JSON.stringify({famille:kind,sujet:title,fait_a_respecter:fact,contexte:'Cas synthétique non publiable; les sources ne sont pas fournies.'})}
 ]};
return [{json:{contract:'cdc-ollama-editorial-benchmark-v1',model,kind,request}}];

const source=$('Préparer essai synthétique').first().json;
const response=$input.first().json;
const limits={title:180,angle:700,summary:2000,research_note:3000};
let fields=null,issues=[];
try{
 if(response.done!==true||typeof response.message?.content!=='string')throw Error('INCOMPLETE');
 fields=JSON.parse(response.message.content);
 if(!fields||typeof fields!=='object'||Array.isArray(fields)
   ||Object.keys(fields).length!==4
   ||Object.keys(fields).some(k=>!(k in limits)))throw Error('SCHEMA');
 for(const [key,max] of Object.entries(limits)){
   if(typeof fields[key]!=='string'||!fields[key].trim()
      ||[...fields[key]].length>max)throw Error('FIELDS');
 }
}catch{fields=null;issues.push('INVALID_OR_INCOMPLETE_RESPONSE');}
return [{json:{
 contract:source.contract,model:source.model,kind:source.kind,
 schema_valid:issues.length===0,issues,
 brief_for_human_review:fields,
 human_approved:false,publishable:false,
 note:'Une sortie JSON correcte ne prouve ni exactitude ni authenticité. Aucune publication.'
}}];
